b:if.script:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://tsn-protocol.blogspot.com/#website",
      "url": "https://tsn-protocol.blogspot.com/",
      "name": "Transfer Settlement Network",
      "inLanguage": "en"
    },
    {
      "@type": "Organization",
      "@id": "https://tsn-protocol.blogspot.com/#trustlink-labs",
      "name": "TrustLink Labs",
      "url": "https://github.com/Trustlink-Labs",
      "sameAs": [
        "https://github.com/Trustlink-Labs",
        "https://github.com/bigdreamsweb3/trustlink-pay",
        "https://x.com/trustlinklabs"
      ],
      "founder": {
        "@type": "Person",
        "name": "Agbaka Matthew Daniel",
        "alternateName": "Big Dreams Web3",
        "url": "https://x.com/0xbigdream"
      },
      "description": "Research and protocol development organization building the Transfer Settlement Network."
    },
    {
      "@type": "WebPage",
      "@id": "https://tsn-protocol.blogspot.com/#knowledge-base",
      "name": "Transfer Settlement Network: Blockchain Payment Infrastructure",
      "headline": "Transfer Settlement Network: Blockchain Payment Infrastructure",
        "description": "An architecture guide to TSN, TIN payment identity, GPRU authorization, encrypted Node commitments, Mother Escrow DNA, TCap private balances, epoch treasury settlement, Crankers, and receipts.",
      "dateCreated": "2026-07-19",
      "datePublished": "2026-07-19",
      "dateModified": "2026-07-30",
      "author": {"@id": "https://tsn-protocol.blogspot.com/#trustlink-labs"},
      "publisher": {"@id": "https://tsn-protocol.blogspot.com/#trustlink-labs"},
      "isPartOf": {"@id": "https://tsn-protocol.blogspot.com/#website"},
      "mainEntity": {
        "@type": "DefinedTerm",
        "name": "Transfer Settlement Network",
        "alternateName": "TSN",
      "description": "Identity-aware payment coordination and settlement infrastructure built on Solana, spanning TIN identity, GPRU authorization, local SDK signing, encrypted Node commitments, Mother DNA, TCap private balances, epoch treasury funding, Cranker execution, and receipts."
      },
      "about": ["Transfer Settlement Network", "TIN payment identity", "GPRU authorization", "TCap private balances", "TSN Node", "Crankers", "Solana settlement"],
      "keywords": "Transfer Settlement Network, TSN, TIN, GPRU, TCap, TSN Node, Cranker, blockchain payment infrastructure, private balance, stablecoin settlement, payment intents",
      "inLanguage": "en"
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is a Transfer Settlement Network?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "TSN is identity-aware payment coordination and settlement infrastructure built on Solana. It includes TIN identity, GPRU authorization, local SDK signing, encrypted Node commitments, Mother-rooted DNA, TCap private balances, epoch treasury funding, Cranker submission, and receipts."
          }
        },
        {
          "@type": "Question",
          "name": "How do TIN, GPRU, and TCap relate to TSN?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "TIN is TSN's 10-digit payment identity. GPRU provides routing and authorization, while TCap provides policy-bound private balance tips and encrypted snapshots. They are components of TSN, not separate settlement networks."
          }
        },
        {
          "@type": "Question",
          "name": "What do the TSN Node and Crankers do?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The TSN Node verifies signed plans, reserves epoch liability, prevents replay, creates Mother-attested settlement authorizations, and tracks status. Crankers pay Solana fees and submit exact DNA-bound transactions without receiving user private keys or payment-specific accounts."
          }
        },
        {
          "@type": "Question",
          "name": "Is TCAP the current TSN settlement system?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. TSN settlement uses the TSN Program, Mother-rooted one-time DNA, opaque deterministic slots, epoch treasury accounting, and TCap encrypted balance commitments for private account state."
          }
        },
        {
          "@type": "Question",
          "name": "How does TSN protect private payment data?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "TSN uses encrypted commitments, GPRU-scoped authorization, Mother-rooted Settlement DNA, and owner-local TCap balance snapshots. Public observers see only the coordination data required for settlement."
          }
        },
        {
          "@type": "Question",
          "name": "Does a TIN prove legal identity?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. A TIN is a 10-digit payment identity. Optional assurance credentials are separate from payment authorization and settlement."
          }
        }
      ]
    },
    {
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Transfer Settlement Network",
          "item": "https://tsn-protocol.blogspot.com/"
        }
      ]
    }
  ]
}

head.b:skin:
    :root{--paper:#f4f0e8;--sheet:#fffdf8;--ink:#191814;--muted:#67635a;--rule:#c9c1b2;--red:#194b34;--gold:#8f6b26;--navy:#05203b;--green:#174d3b;--max:1180px;--reading:760px}
