    a{color:var(--green);text-decoration-thickness:.08em;text-underline-offset:.18em}a:hover{color:var(--red)}a:focus-visible,summary:focus-visible{outline:3px solid var(--red);outline-offset:4px}.skip{position:fixed;left:1rem;top:-5rem;z-index:99;background:var(--ink);color:white;padding:.7rem 1rem}.skip:focus{top:1rem}
