    .brand a{color:var(--ink);text-decoration:none}.site-nav-wrap{position:relative;display:flex;align-items:center;gap:.65rem;min-width:0;flex:1 1 auto}.site-nav{display:flex;flex:1 1 auto;min-width:0;overflow:hidden}.nav-more{position:relative;flex:0 0 auto;font-family:Arial,"Helvetica Neue",sans-serif}.nav-more-button[hidden],.nav-more-menu[hidden]{display:none!important}.nav-more-menu{position:absolute;right:0;top:calc(100% + .65rem);z-index:150;width:min(280px,82vw);padding:.45rem;border:1px solid var(--rule);background:var(--sheet);box-shadow:0 14px 34px rgba(25,24,20,.18)}.nav-more-menu ul{display:grid;margin:0;padding:0;list-style:none}.nav-more-menu li{margin:0;padding:0}.nav-more-menu a{display:block;padding:.7rem .75rem;color:var(--ink);text-decoration:none;font:700 .72rem/1.35 Arial,"Helvetica Neue",sans-serif;white-space:normal}.nav-more-menu a:hover,.nav-more-menu .selected a{background:var(--paper);color:var(--red)}.nav-more-button.has-current{color:var(--red)}.site-nav{display:flex;flex:1 1 auto;min-width:0;align-items:center;gap:.85rem;max-width:100%;font:600 .7rem/1.3 Arial,"Helvetica Neue",sans-serif;white-space:nowrap;overflow-x:auto;overflow-y:hidden;scrollbar-width:none;-ms-overflow-style:none}.site-nav::-webkit-scrollbar{display:none}.site-nav .site-nav-section{flex:0 0 auto;min-width:max-content}.site-nav .widget,.site-nav .widget-content{margin:0;padding:0}.site-nav h2{display:none}.site-nav ul{display:flex;align-items:center;gap:.85rem;width:max-content;list-style:none;margin:0;padding:0}.site-nav li{flex:0 0 auto;margin:0;padding:0}.site-nav a{display:block;flex:0 0 auto;scroll-snap-align:start;color:var(--muted);text-decoration:none;padding:.35rem 0}.site-nav a:hover,.site-nav .selected a,.site-nav a.active,.site-nav .updates-link.active{color:var(--red)}.latest-updates{margin-top:1.5rem;padding-top:1.25rem;border-top:1px solid var(--rule)}.latest-updates h2{margin-bottom:.75rem}.latest-posts{display:flex;gap:.75rem;overflow-x:auto;padding:0 0 .65rem;scrollbar-width:none;-webkit-overflow-scrolling:touch;scroll-snap-type:x proximity}.latest-posts::-webkit-scrollbar{display:none}.latest-posts .latest-post{flex:0 0 min(76vw,260px);padding:.85rem;border:1px solid var(--rule);border-radius:8px;background:var(--sheet);scroll-snap-align:start;text-decoration:none;display:block}.latest-posts .latest-post strong{display:block;color:var(--ink);font:700 .82rem/1.3 Arial,"Helvetica Neue",sans-serif}.latest-posts .latest-post time{display:block;margin-top:.3rem;color:var(--muted);font:600 .62rem/1.2 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.06em}.latest-posts .latest-post:hover strong{color:var(--red)}.latest-post{display:block;text-decoration:none}.latest-post strong{display:block;color:var(--ink);font:700 .78rem/1.3 Arial,"Helvetica Neue",sans-serif}.latest-post time{display:block;margin-top:.2rem;color:var(--muted);font:600 .6rem/1.2 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.06em}.latest-post:hover strong{color:var(--red)}.all-updates{display:inline-block;margin-top:1rem;color:var(--red)!important;font-weight:800!important}.updates-index-head{margin-bottom:2.5rem;padding-bottom:1.5rem;border-bottom:3px double var(--ink)}.updates-index-head small{color:var(--red);font:800 .7rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.14em;text-transform:uppercase}.updates-index-head h1{margin:.55rem 0 .8rem!important;padding:0!important;border:0!important}.updates-index-head p{margin:0;color:var(--muted)}.updates-search{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.65rem;margin-top:1.4rem}.updates-search input{width:100%;min-height:48px;padding:.75rem 1rem;border:1px solid var(--rule);border-radius:8px;background:var(--sheet);color:var(--ink);font:400 1rem/1.3 Arial,"Helvetica Neue",sans-serif}.updates-search input:focus{outline:2px solid var(--green);outline-offset:2px}.updates-search button,.updates-more{min-height:48px;padding:.7rem 1.15rem;border:1px solid var(--ink);border-radius:8px;background:var(--ink);color:var(--sheet);font:800 .75rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.06em;text-transform:uppercase;cursor:pointer}.updates-search button:hover,.updates-more:hover{background:var(--red);border-color:var(--red)}.updates-status{margin:1rem 0;color:var(--muted);font:600 .72rem/1.4 Arial,"Helvetica Neue",sans-serif}.updates-more-wrap{padding-top:1.5rem;text-align:center}.updates-more[hidden]{display:none}.updates-more:disabled{opacity:.55;cursor:wait}@media(max-width:520px){.updates-search{grid-template-columns:1fr}.updates-search button{width:100%}}.updates-results{display:grid;gap:0}.update-result{padding:1.7rem 0;border-bottom:1px solid var(--rule)}.update-result:first-child{padding-top:0}.update-result h2{margin:.3rem 0 .65rem;font-size:clamp(1.45rem,3vw,2.1rem);line-height:1.12}.update-result h2 a{color:var(--ink);text-decoration:none}.update-result h2 a:hover{color:var(--red)}.update-result time{color:var(--green);font:700 .68rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.07em;text-transform:uppercase}.update-result p{margin:0;color:var(--muted);font-size:.95rem}.update-labels{margin-top:.7rem;color:var(--red);font:700 .65rem/1.3 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.06em}.updates-empty{padding:2rem;border:1px solid var(--rule);background:var(--sheet);text-align:center;color:var(--muted)}.mobile-toc-fab{display:none;position:fixed;right:1rem;bottom:1.3rem;z-index:120;align-items:center;gap:.5rem;min-height:46px;padding:.72rem .9rem;border:1px solid var(--ink);background:rgba(255,253,248,.9);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);color:var(--ink);box-shadow:0 8px 28px rgba(25,24,20,.18);font:800 .68rem/1 Arial,"Helvetica Neue",sans-serif;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}.mobile-toc-fab.visible{display:flex}.mobile-toc-fab b{font-size:1.05rem;color:var(--red)}.mobile-drawer-overlay{position:fixed;inset:0;z-index:129;background:rgba(25,24,20,.48);opacity:0;visibility:hidden;transition:opacity .2s ease,visibility .2s ease}.mobile-drawer-overlay.open{opacity:1;visibility:visible}.mobile-toc-drawer{position:fixed;inset:0 0 0 auto;z-index:130;width:min(88vw,380px);padding:0 1rem 1.2rem;overflow-y:auto;overscroll-behavior:contain;background:var(--paper);border-left:1px solid var(--rule);box-shadow:-12px 0 40px rgba(25,24,20,.2);transform:translateX(102%);transition:transform .24s ease}.mobile-toc-drawer.open{transform:translateX(0)}.mobile-drawer-head{position:sticky;top:0;display:flex;align-items:center;justify-content:space-between;gap:.75rem;padding:1rem 0 .9rem;border-bottom:1px solid var(--rule);background:var(--paper);z-index:2}.mobile-drawer-head strong{font:800 .68rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--ink)}.mobile-drawer-close{width:2.15rem;height:2.15rem;border:1px solid var(--rule);background:transparent;color:var(--ink);font-size:1.3rem;line-height:1;cursor:pointer}.mobile-drawer-close:hover{border-color:var(--red);color:var(--red)}.mobile-drawer-content{padding:1rem 0 0}.mobile-drawer-content h2{margin:1.1rem 0 .75rem;padding:0;border:0;font:800 .68rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.16em;text-transform:uppercase;color:var(--ink)}.mobile-drawer-links,.mobile-drawer-content .widget-content,.mobile-drawer-content ul,.mobile-drawer-content ol{list-style:none;padding:0;margin:0}.mobile-drawer-links li,.mobile-drawer-content .widget-content li{border-top:1px solid var(--rule)}.mobile-drawer-links a,.mobile-drawer-content .widget-content a,.mobile-drawer-content a{display:block;padding:.7rem .1rem;color:var(--ink);text-decoration:none;font:700 .76rem/1.35 Arial,"Helvetica Neue",sans-serif}.mobile-drawer-links a:hover,.mobile-drawer-links a.active,.mobile-drawer-content .widget-content a:hover{color:var(--red)}.mobile-drawer-content .widget-content li:last-child,.mobile-drawer-links li:last-child{border-bottom:1px solid var(--rule)}.mobile-drawer-all{display:inline-flex;align-items:center;gap:.4rem;margin-top:1rem;padding-top:.8rem;border-top:1px solid var(--rule);color:var(--green);text-decoration:none;font:800 .68rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.12em;text-transform:uppercase}.mobile-drawer-all:hover{color:var(--red)}.mobile-drawer-content .latest-updates{margin-top:1rem}.mobile-drawer-content .latest-updates h2{margin-top:1rem}.mobile-drawer-content .latest-updates .widget-content li{padding:.32rem 0}.mobile-drawer-content .latest-updates .widget-content .item-title,.mobile-drawer-content .latest-updates .widget-content .item-title a{font-size:.72rem;line-height:1.4}.mobile-toc-drawer.open{transform:translateX(0)}.mobile-drawer-head{position:sticky;top:-1rem;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:1rem;margin:-1rem -1rem 1rem;padding:1rem;border-bottom:1px solid var(--rule);background:rgba(244,240,232,.97)}.mobile-drawer-head strong{font:800 .78rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.1em;text-transform:uppercase}.mobile-drawer-close{display:grid;place-items:center;width:36px;height:36px;padding:0;border:1px solid var(--rule);border-radius:50%;background:var(--sheet);color:var(--ink);font-size:1.2rem;cursor:pointer}.mobile-drawer-content h2{margin:1.25rem 0 .75rem;font-size:.75rem;text-transform:uppercase;letter-spacing:.1em}.mobile-drawer-links{margin:0;padding:0;list-style:none}.mobile-drawer-links li{border-bottom:1px solid var(--rule)}.mobile-drawer-links a{display:block;padding:.75rem 0;color:var(--ink);text-decoration:none;font:700 .78rem/1.35 Arial,"Helvetica Neue",sans-serif}.mobile-drawer-links a:hover{color:var(--red)}.mobile-latest-posts{display:grid;gap:.65rem}.mobile-latest-posts .latest-post{padding:.75rem;border:1px solid var(--rule);border-radius:8px;background:var(--sheet)}.mobile-drawer-all{display:inline-block;margin-top:1rem;color:var(--red);font:800 .72rem/1.2 Arial,"Helvetica Neue",sans-serif;text-decoration:none}body.mobile-drawer-open{overflow:hidden}@media(max-width:820px){.latest-updates{overflow:hidden}.all-updates{margin-top:.35rem}}@media(min-width:821px){.mobile-toc-fab,.mobile-drawer-overlay,.mobile-toc-drawer{display:none!important}}@media(prefers-reduced-motion:reduce){.mobile-drawer-overlay,.mobile-toc-drawer{transition:none}}.page-shell.auto-toc-shell{width:min(var(--max),calc(100% - 2.4rem))}.page-section.has-auto-toc{display:grid;grid-template-columns:220px minmax(0,1fr);gap:clamp(2rem,4vw,4rem);align-items:start}.page-section.has-auto-toc&gt;.widget,.page-section.has-auto-toc&gt;.post-outer{min-width:0}.auto-toc{position:sticky;top:1.5rem;max-height:calc(100vh - 3rem);overflow-y:auto;padding-right:.8rem;border-right:1px solid var(--rule);scrollbar-width:thin}.auto-toc h2,.auto-toc .auto-toc-label{margin:0 0 .8rem;font:800 .72rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.11em;text-transform:uppercase}.auto-toc ol{margin:0;padding:0;list-style:none}.auto-toc li{margin:0}.auto-toc a{display:block;padding:.38rem 0;color:var(--muted);text-decoration:none;font:600 .68rem/1.35 Arial,"Helvetica Neue",sans-serif}.auto-toc a:hover,.auto-toc a.active{color:var(--red)}.auto-toc .toc-level-3 a{padding-left:.8rem;font-weight:500}.post-body h2[id],.post-body h3[id]{scroll-margin-top:1.5rem}@media(max-width:820px){.page-shell.auto-toc-shell{width:calc(100% - 2rem)}.page-section.has-auto-toc{display:block}.auto-toc{display:none}.auto-page-fab{display:none}.auto-page-fab.visible{display:flex}}@media(min-width:821px){.auto-page-fab,.auto-page-overlay,.auto-page-drawer{display:none!important}}.share-tools{display:grid;grid-template-rows:auto auto;gap:.35rem;max-width:100%;margin:1rem 0 2rem;padding:.65rem 0;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);font-family:Arial,"Helvetica Neue",sans-serif}.share-tools-label{color:var(--muted);font-size:.62rem;font-weight:900;letter-spacing:.1em;text-transform:uppercase}.share-tools-buttons{display:flex;align-items:center;gap:.42rem;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;scroll-snap-type:x proximity}.share-tools-buttons::-webkit-scrollbar{display:none}.share-tool{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;min-height:44px;min-width:44px;padding:.2rem .35rem;border:0;border-radius:0;background:transparent;color:var(--ink);text-decoration:none;font:800 .68rem/1 Arial,"Helvetica Neue",sans-serif;cursor:pointer;scroll-snap-align:start}.share-tool:hover,.share-tool:focus-visible{color:var(--red);text-decoration:underline;text-underline-offset:.2em;outline:none}.share-copy.copied{color:var(--green)}.share-icon{display:block;line-height:1;white-space:nowrap}.hero .share-tools{max-width:var(--reading);margin-top:1.2rem}.page-shell .post-title+.share-tools{margin-top:-1rem}.share-tools-bottom{margin-top:2.5rem}.share-tools[hidden]{display:none}@media(max-width:600px){.share-tools{margin-bottom:1.5rem;padding-bottom:.7rem}.share-tool{padding:.3rem 0}}@media print{.share-tools{display:none!important}}.page-shell{width:min(900px,calc(100% - 2.4rem));margin:0 auto;padding:4rem 0 6rem}.homepage-page-shell{display:none}.page-section{display:block}.page-shell .widget,.page-shell .blog-posts,.page-shell .post-outer{margin:0;padding:0}.page-shell .post-title,.page-shell h1{font-size:clamp(2.2rem,6vw,4rem);line-height:1.05;letter-spacing:-.04em;margin:0 0 2rem;padding-bottom:1rem;border-bottom:3px double var(--ink)}.page-shell .post-body{font-size:1.05rem;min-width:0}.page-shell .post-body img{max-width:100%;height:auto}.page-shell .post-header,.page-shell .blog-pager,.page-shell .post-footer-line,.page-shell .byline,.page-shell .post-share-buttons{display:none!important}.page-shell .post-footer{display:block!important}.page-shell .author-card{display:flex!important}.brand{flex:0 0 auto;white-space:nowrap;font-weight:700;text-transform:uppercase;letter-spacing:.13em;font-size:.82rem}.edition{flex:0 0 auto;white-space:nowrap;font-size:.7rem;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}.hero{max-width:var(--max);margin:auto;padding:5.5rem 1.2rem 3.4rem;border-bottom:4px double var(--ink)}
    .kicker{font:700 .75rem/1.2 Arial,"Helvetica Neue",sans-serif;letter-spacing:.18em;text-transform:uppercase;color:var(--red);display:flex;align-items:center;gap:.8rem}.kicker:before{content:"";width:2.5rem;height:2px;background:var(--red)}h1{font-size:clamp(2.55rem,7vw,6.6rem);line-height:.96;letter-spacing:-.055em;max-width:1100px;margin:1.3rem 0 1.7rem}.dek{font-size:clamp(1.1rem,2vw,1.45rem);line-height:1.55;max-width:820px;color:#3f3c35}.byline{display:flex;gap:1.4rem;flex-wrap:wrap;margin-top:2rem;padding-top:1rem;border-top:1px solid var(--rule);font:500 .78rem/1.5 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.08em}.byline span:last-child{color:var(--muted)}
