    /* Reserve stable header/content space while Blogger feeds resolve. */
    .site-nav-wrap{flex:1 1 auto;width:auto;min-height:1.8rem;justify-content:center}
    .site-nav{flex:0 1 auto;width:fit-content}
    .nav-more{display:flex;align-items:center;margin-left:.3rem}
   .nav-more-button{
  display:inline-flex;
  align-items:center;
  justify-content:center;

  height:0.8rem;
  max-height:1.8rem;
  box-sizing:border-box;
  margin-block:auto;

  padding:0 .45rem;
  border:1px solid var(--ink);
  background:var(--red);
  color:#fff;
  cursor:pointer;
  line-height:1;
  white-space:nowrap;
  transition:background .15s,border-color .15s;
}
    .nav-more-button:hover,.nav-more-button[aria-expanded=true]{background:var(--red);border-color:var(--red);color:var(--gold)}
    .nav-more-button svg{flex:0 0 auto;display:block}
    .page-section{min-height:65vh}
    .page-section.content-loading{position:relative}
    .page-section.content-loading:before{content:"Loading publication\2026";display:block;width:min(100%,34rem);margin:.35rem 0;padding:1rem 0;border-top:3px double var(--ink);border-bottom:1px solid var(--rule);color:var(--muted);font:700 .68rem/1.4 Arial,"Helvetica Neue",sans-serif;letter-spacing:.1em;text-transform:uppercase}
    @media(max-width:600px){.site-nav-wrap{width:100%;justify-content:flex-start;gap:.9rem}.site-nav{flex:0 0 auto}.site-nav ul{gap:.9rem}.page-section{min-height:72vh}}

    /* Search is a full-width application view. It must not inherit the article
       TOC grid or leave its pagination control in a separate narrow column. */
    #main-content:has(.updates-index-head),
    #main-content:has(.updates-results),
    #main-content:has(.updates-search){width:min(900px,calc(100% - 2.4rem));min-width:0}
    #main-content:has(.updates-index-head) .page-section,
    #main-content:has(.updates-results) .page-section,
    #main-content:has(.updates-search) .page-section{display:block;min-width:0;width:100%}
    #main-content:has(.updates-index-head) .updates-index-head,
    #main-content:has(.updates-index-head) .updates-status,
    #main-content:has(.updates-index-head) .updates-results,
    #main-content:has(.updates-index-head) .updates-more-wrap{width:100%;max-width:none;min-width:0}
    .updates-more-wrap{display:flex;justify-content:center;align-items:center;width:100%;min-height:48px}
    @media(max-width:600px){#main-content:has(.updates-index-head),#main-content:has(.updates-results),#main-content:has(.updates-search){width:calc(100% - 2rem)}}
    /* Breadcrumb */
    .post-breadcrumb{display:flex;flex-wrap:wrap;align-items:center;gap:.3rem .45rem;margin-bottom:1.5rem;font:600 .68rem/1.3 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.post-breadcrumb a{color:var(--muted);text-decoration:none}.post-breadcrumb a:hover{color:var(--red)}.post-breadcrumb .bc-sep{color:var(--rule);font-size:.8em}.post-breadcrumb .bc-current{color:var(--ink);font-weight:700}@media print{.post-breadcrumb{display:none}}
    /* Post Tags */
