    /* Author Card */
    .author-card{display:flex;gap:1.25rem;align-items:flex-start;margin:3rem 0 0;padding:1.5rem;border:1px solid var(--rule);border-left:4px solid var(--ink);background:var(--sheet)}.author-card-photo{width:64px;height:64px;border-radius:50%;object-fit:cover;flex:0 0 64px;border:2px solid var(--rule)}.author-card-body{display:flex;flex-direction:column;gap:.35rem;min-width:0}.author-card-label{margin:0;font:700 .62rem/1.2 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)}.author-card-name{display:inline-flex;align-items:center;min-height:44px;padding:.5rem .25rem;margin:-.5rem -.25rem;font:800 1rem/1.2 Arial,"Helvetica Neue",sans-serif;color:var(--ink);text-decoration:none;letter-spacing:-.01em}.author-card-name:hover{color:var(--red)}.author-card-bio{margin:0;font:400 .88rem/1.6 Arial,"Helvetica Neue",sans-serif;color:var(--muted)}.author-card-meta{display:flex;align-items:center;gap:.5rem;font:700 .65rem/1.2 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.author-card-meta a{display:inline-flex;align-items:center;min-height:44px;padding:.5rem .25rem;margin:-.5rem -.25rem;color:var(--red);text-decoration:none}.author-card-meta a:hover{text-decoration:underline}.author-card-sep{color:var(--rule)}@media(max-width:500px){.author-card{flex-direction:column;gap:1rem}.author-card-photo{width:52px;height:52px;flex:0 0 52px}}
    /* Footer */
    .footer{display:block;max-width:none;margin:0;padding:0;border-top:3px double var(--ink);background:var(--ink);color:var(--sheet);font:500 .7rem/1.5 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.08em}.footer-inner{display:grid;grid-template-columns:minmax(150px,1fr) minmax(0,3.2fr) minmax(150px,1fr);align-items:center;gap:clamp(1.5rem,3vw,3.5rem);width:min(var(--max),calc(100% - 3rem));margin:0 auto;padding:2rem 0}.footer-pages,.footer-pages .widget,.footer-pages .widget-content{width:auto!important;min-width:0;margin:0;padding:0}.footer-brand{display:flex;flex-direction:column;gap:.2rem;min-width:0}.footer-brand strong{font:800 .82rem/1.2 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.12em;color:#fff}.footer-brand span{font:500 .65rem/1.3 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#ccc7be}.footer-links{display:flex;align-items:center;justify-content:center;gap:.65rem 1.3rem;min-width:0;flex-wrap:wrap}.footer-links a{color:#e8e4de;text-decoration:none;font:700 .68rem/1.2 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.09em;white-space:nowrap;overflow-wrap:normal;word-break:normal}.footer-links a:hover{color:#fff}.footer-copy{display:flex;flex-direction:column;align-items:flex-end;gap:.2rem;min-width:0;text-align:right}.footer-copy span{font:500 .65rem/1.3 Arial,"Helvetica Neue",sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#ccc7be}.blogger-system,.layout-extra,.Attribution,.BlogSearch,.blogger,.image-attribution{display:none!important}@media(max-width:820px){.footer-inner{grid-template-columns:1fr;gap:1.35rem;text-align:center}.footer-brand,.footer-copy{align-items:center;text-align:center}.footer-links{gap:.7rem 1rem}}@media(max-width:600px){.footer-inner{width:calc(100% - 2rem);padding:1.7rem 0}.footer-links{gap:.75rem 1rem}}
    .back-to-top { position: fixed; bottom: 11rem; right: 1rem; width: 60px; height: 60px; background: rgba(255, 255, 255, 0.5); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.4); border-radius: 16px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); display: flex; flex-direction: column; align-items: center; justify-content: center; cursor: pointer; opacity: 0; visibility: hidden; transition: opacity 0.3s, visibility 0.3s, transform 0.2s, background 0.2s, box-shadow 0.2s; z-index: 100; gap: 4px; padding: 6px 0; }
    .back-to-top svg { color: var(--red); filter: drop-shadow(0 2px 4px rgba(0,0,0,0.15)); width: 28px; height: 28px; }
    .back-to-top span { font-size: 0.5rem; font-weight: 800; color: var(--ink); text-shadow: 0 1px 3px rgba(255,255,255,0.9), 0 0 8px rgba(255,255,255,1); line-height: 1; text-transform: uppercase; letter-spacing: 0; }
    .back-to-top.visible { opacity: 1; visibility: visible; }
    .back-to-top:hover { transform: translateY(-5px); background: rgba(255, 255, 255, 0.7); box-shadow: 0 6px 20px rgba(0,0,0,0.08); }
    .up-kicker{font:800 .68rem/1.2 Arial,sans-serif;letter-spacing:.18em;text-transform:uppercase;color:var(--red);display:flex;align-items:center;gap:.65rem;margin-bottom:.65rem}.up-kicker:before{content:"";width:2rem;height:2px;background:var(--red);flex:0 0 auto}.tsn-document>.eyebrow{display:none}

body.script:
