      if(updatesLink&&(isIndex||isPost||isLabelPage)){updatesLink.classList.add('active');var li=updatesLink.closest('li');if(li){li.classList.add('selected');}}Array.prototype.slice.call(document.querySelectorAll('.site-nav a')).forEach(function(link){var destination=link.href.split(/[?#]/)[0].replace(/\/$/,'');if(destination===current){var item=link.closest('li');if(item){item.classList.add('selected');}}});
      var moreWrap=document.querySelector('.nav-more'),moreButton=document.querySelector('.nav-more-button'),moreMenu=document.getElementById('nav-more-menu'),moreList=moreMenu&&moreMenu.querySelector('ul'),arrangingNav=false;
