      var homepageToc=document.querySelector('.toc'),drawerButton=document.getElementById('mobile-toc-fab'),drawer=document.getElementById('mobile-toc-drawer'),drawerOverlay=document.getElementById('mobile-drawer-overlay'),drawerClose=document.getElementById('mobile-drawer-close'),drawerLinks=document.getElementById('mobile-drawer-links'),mobileLatest=document.getElementById('mobile-latest-posts'),lastFocus=null;function syncMobileLatest(){if(!mobileLatest||!latest){return;}var posts=latest.querySelectorAll('.latest-post');if(!posts.length){return;}mobileLatest.innerHTML='';posts.forEach(function(post){mobileLatest.appendChild(post.cloneNode(true));});}function closeDrawer(){if(!drawerButton||!drawer){return;}drawer.classList.remove('open');drawerOverlay.classList.remove('open');drawerButton.setAttribute('aria-expanded','false');drawerOverlay.setAttribute('aria-hidden','true');drawer.setAttribute('aria-hidden','true');drawer.setAttribute('inert','');document.body.classList.remove('mobile-drawer-open');if(lastFocus){lastFocus.focus();}}function openDrawer(){if(!drawerButton||!drawer){return;}lastFocus=document.activeElement;drawer.removeAttribute('inert');drawer.setAttribute('aria-hidden','false');drawer.classList.add('open');drawerOverlay.classList.add('open');drawerButton.setAttribute('aria-expanded','true');drawerOverlay.setAttribute('aria-hidden','false');document.body.classList.add('mobile-drawer-open');drawerClose.focus();}if(homepageToc&&drawerButton&&drawer&&drawerLinks){var sourceList=homepageToc.querySelector('ol');if(sourceList){drawerLinks.innerHTML=sourceList.innerHTML;}drawerButton.addEventListener('click',openDrawer);drawerClose.addEventListener('click',closeDrawer);drawerOverlay.addEventListener('click',closeDrawer);drawerLinks.addEventListener('click',function(event){if(event.target.closest('a')){closeDrawer();}});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&drawer.classList.contains('open')){closeDrawer();}});/* Use IntersectionObserver instead of getBoundingClientRect on scroll */if(window.IntersectionObserver){new IntersectionObserver(function(entries){drawerButton.classList.toggle('visible',window.innerWidth<=820&&!entries[0].isIntersecting);},{threshold:0}).observe(homepageToc);}else{var _tocBottom=homepageToc.offsetTop+homepageToc.offsetHeight;window.addEventListener('scroll',function(){drawerButton.classList.toggle('visible',window.innerWidth<=820&&window.scrollY>_tocBottom);},{passive:true});}if(latest&&mobileLatest){new MutationObserver(function(){syncMobileLatest();}).observe(latest,{childList:true,subtree:true});setTimeout(function(){syncMobileLatest();},500);}}      function buildAutomaticToc(){
        if(isIndex||isHome||!page||page.querySelector('.auto-toc')){return;}var body=page.querySelector('.post-body');if(!body){return;}var headings=[].slice.call(body.querySelectorAll('h2,h3')).filter(function(heading){return heading.textContent.trim().length;});if(headings.length<2){return;}
        var used={};function slug(textValue){var base=textValue.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s-]/g,'').trim().replace(/\s+/g,'-').replace(/-+/g,'-')||'section',value=base,count=2;while(used[value]||document.getElementById(value)){value=base+'-'+count++;}used[value]=true;return value;}
        var toc=document.createElement('nav'),title=document.createElement('p'),list=document.createElement('ol');toc.className='auto-toc';toc.setAttribute('aria-label','On this page');title.className='auto-toc-label';title.textContent='On this page';toc.appendChild(title);toc.appendChild(list);headings.forEach(function(heading){if(!heading.id){heading.id=slug(heading.textContent);}else{used[heading.id]=true;}var item=document.createElement('li'),link=document.createElement('a');item.className='toc-level-'+heading.tagName.slice(1);link.href='#'+heading.id;link.textContent=heading.textContent.trim();item.appendChild(link);list.appendChild(item);});page.insertBefore(toc,page.firstChild);page.classList.add('has-auto-toc');var shell=page.closest('.page-shell');if(shell){shell.classList.add('auto-toc-shell');}
        var fab=document.createElement('button'),overlay=document.createElement('div'),drawer=document.createElement('div'),head=document.createElement('div'),drawerTitle=document.createElement('strong'),close=document.createElement('button'),content=document.createElement('div'),mobileList=document.createElement('ol'),last=null;fab.className='mobile-toc-fab auto-page-fab';fab.type='button';fab.setAttribute('aria-expanded','false');fab.setAttribute('aria-label','Open table of contents');fab.innerHTML='<b aria-hidden="true">☰</b><span>Contents</span>';overlay.className='mobile-drawer-overlay auto-page-overlay';overlay.setAttribute('aria-hidden','true');drawer.className='mobile-toc-drawer auto-page-drawer';drawer.setAttribute('aria-hidden','true');drawer.setAttribute('aria-modal','true');drawer.setAttribute('role','dialog');drawer.setAttribute('inert','');head.className='mobile-drawer-head';drawerTitle.textContent='On this page';close.className='mobile-drawer-close';close.type='button';close.setAttribute('aria-label','Close table of contents');close.innerHTML='×';content.className='mobile-drawer-content';mobileList.className='mobile-drawer-links';mobileList.innerHTML=list.innerHTML;head.appendChild(drawerTitle);head.appendChild(close);content.appendChild(mobileList);drawer.appendChild(head);drawer.appendChild(content);document.body.appendChild(fab);document.body.appendChild(overlay);document.body.appendChild(drawer);
        function closeAuto(){drawer.classList.remove('open');overlay.classList.remove('open');fab.setAttribute('aria-expanded','false');overlay.setAttribute('aria-hidden','true');drawer.setAttribute('aria-hidden','true');drawer.setAttribute('inert','');document.body.classList.remove('mobile-drawer-open');if(last){last.focus();}}function openAuto(){last=document.activeElement;drawer.removeAttribute('inert');drawer.setAttribute('aria-hidden','false');drawer.classList.add('open');overlay.classList.add('open');fab.setAttribute('aria-expanded','true');overlay.setAttribute('aria-hidden','false');document.body.classList.add('mobile-drawer-open');close.focus();}fab.addEventListener('click',openAuto);close.addEventListener('click',closeAuto);overlay.addEventListener('click',closeAuto);mobileList.addEventListener('click',function(event){if(event.target.closest('a')){closeAuto();}});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&drawer.classList.contains('open')){closeAuto();}});/* Use IntersectionObserver for fab visibility — no getBoundingClientRect on scroll */if(window.IntersectionObserver){var _sentinel=document.createElement('div');_sentinel.style.cssText='position:absolute;top:120px;left:0;width:1px;height:1px;pointer-events:none;';body.appendChild(_sentinel);new IntersectionObserver(function(entries){fab.classList.toggle('visible',window.innerWidth<=820&&!entries[0].isIntersecting);},{threshold:0}).observe(_sentinel);}else{var _bodyTop=body.offsetTop+120;window.addEventListener('scroll',function(){fab.classList.toggle('visible',window.innerWidth<=820&&window.scrollY>_bodyTop);},{passive:true});}
        var tocLinks=[].slice.call(toc.querySelectorAll('a'));/* Cache offsetTop values once — avoids forced reflow on every scroll tick */var _headingTops=headings.map(function(h){return{id:h.id,top:h.offsetTop};});function updateActive(){var scrollY=window.scrollY+160,active='';_headingTops.forEach(function(h){if(scrollY>h.top){active='#'+h.id;}});tocLinks.forEach(function(link){link.classList.toggle('active',link.getAttribute('href')===active);});}window.addEventListener('scroll',updateActive,{passive:true});window.addEventListener('resize',function(){_headingTops=headings.map(function(h){return{id:h.id,top:h.offsetTop};});},{passive:true});updateActive();
      }
      /* Search results are an application view, not an article: never inject the
