      if(page&&!isIndex&&!isSearch&&!isLabelPage&&!isHome){new MutationObserver(buildAutomaticToc).observe(page,{childList:true,subtree:true});buildAutomaticToc();}
      function addShareTools(){
        if(isIndex){return;}var topTarget=isHome?document.querySelector('.hero .byline'):page&&page.querySelector('.post-title'),bottomTarget=isHome?document.querySelector('.author-wrap'):page&&page.querySelector('.post-body');if(!topTarget||!bottomTarget){return;}var url=location.href.split('#')[0].replace(/[?&]m=1/,'').replace(/\?$/,'').replace(/&$/,''),titleNode=isHome?document.querySelector('.hero h1'):topTarget,titleText=titleNode.textContent.trim();
        function iconButton(element,name,symbol,className){element.className='share-tool '+(className||'');element.setAttribute('aria-label',name);element.title=name;var icon=document.createElement('span');icon.className='share-icon';icon.setAttribute('aria-hidden','true');icon.textContent=symbol;element.appendChild(icon);}
        function createTools(position){var tools=document.createElement('nav'),label=document.createElement('span'),buttonsRow=document.createElement('div');tools.className='share-tools share-tools-'+position;tools.setAttribute('aria-label',position==='top'?'Share this page':'Share this page after reading');label.className='share-tools-label';label.textContent='Share';buttonsRow.className='share-tools-buttons';tools.appendChild(label);tools.appendChild(buttonsRow);
          function social(name,symbol,href,className){var anchor=document.createElement('a');anchor.href=href;anchor.target='_blank';anchor.rel='noopener noreferrer';iconButton(anchor,'Share on '+name,symbol,className);buttonsRow.appendChild(anchor);}
          social('X','X','https://twitter.com/intent/tweet?text='+encodeURIComponent(titleText)+'&url='+encodeURIComponent(url),'share-x');social('Facebook','Facebook','https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(url),'share-facebook');social('Reddit','Reddit','https://www.reddit.com/submit?url='+encodeURIComponent(url)+'&title='+encodeURIComponent(titleText),'share-reddit');social('LinkedIn','LinkedIn','https://www.linkedin.com/sharing/share-offsite/?url='+encodeURIComponent(url),'share-linkedin');social('WhatsApp','WhatsApp','https://wa.me/?text='+encodeURIComponent(titleText+' '+url),'share-whatsapp');social('Email','Email','mailto:?subject='+encodeURIComponent(titleText)+'&body='+encodeURIComponent(url),'share-email');
          var copy=document.createElement('button');copy.type='button';iconButton(copy,'Copy link','Copy link','share-copy');copy.addEventListener('click',function(){var icon=copy.querySelector('.share-icon'),done=function(){icon.textContent='Copied';copy.classList.add('copied');copy.setAttribute('aria-label','Link copied');setTimeout(function(){icon.textContent='Copy link';copy.classList.remove('copied');copy.setAttribute('aria-label','Copy link');},1800);};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(url).then(done).catch(function(){});}else{var field=document.createElement('textarea');field.value=url;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();try{document.execCommand('copy');done();}catch(error){}field.remove();}});buttonsRow.appendChild(copy);return tools;
        }
        if(!document.querySelector('.share-tools-top')){var topSlot=document.querySelector('.share-slot-top');if(topSlot){topSlot.appendChild(createTools('top'));}else{topTarget.insertAdjacentElement('afterend',createTools('top'));}}if(!document.querySelector('.share-tools-bottom')){bottomTarget.insertAdjacentElement('afterend',createTools('bottom'));}
      }
      if(isHome){addShareTools();}else if(page&&!isIndex&&!isSearch){new MutationObserver(addShareTools).observe(page,{childList:true,subtree:true});addShareTools();}
function alternate(entry){return(entry.link||[]).filter(function(link){return link.rel==='alternate';})[0];}
      function plain(entry){var box=document.createElement('div');box.innerHTML=(entry.summary&&entry.summary.$t)||(entry.content&&entry.content.$t)||'';return(box.textContent||'').replace(/\s+/g,' ').trim();}
      function dateOf(entry){var value=(entry.published&&entry.published.$t)||'';if(!value){return'';}return new Date(value).toLocaleDateString('en',{year:'numeric',month:'short',day:'numeric'});}
      if(latest){
        var _fetchLatest=function(){fetch('/feeds/posts/default?alt=json&max-results=5').then(function(r){return r.json();}).then(function(data){var entries=(data.feed&&data.feed.entry)||[];latest.innerHTML='';entries.forEach(function(entry){var alt=alternate(entry);if(!alt){return;}var link=document.createElement('a'),title=document.createElement('strong'),time=document.createElement('time');link.className='latest-post';link.href=alt.href;title.textContent=entry.title.$t;time.textContent=dateOf(entry);link.appendChild(title);link.appendChild(time);latest.appendChild(link);});if(!latest.children.length){latest.innerHTML='<small>No updates published yet.</small>';}}).catch(function(){latest.innerHTML='<small>Updates are temporarily unavailable.</small>';});};
        /* Fetch latest for mobile drawer only - homepage uses native Blog2 widget */if(mobileLatest&&!latest.querySelector('.latest-post')){var _fetchLatest=function(){fetch('/feeds/posts/default?alt=json&max-results=5').then(function(r){return r.json();}).then(function(data){var entries=(data.feed&&data.feed.entry)||[];if(latest.querySelector('.latest-post')){syncMobileLatest();return;}latest.innerHTML='';entries.forEach(function(entry){var alt=entry.link&&entry.link.filter(function(l){return l.rel==='alternate';})[0];if(!alt){return;}var link=document.createElement('a'),title=document.createElement('strong'),time=document.createElement('time');link.className='latest-post';link.href=alt.href;title.textContent=entry.title.$t;time.textContent=entry.published&&entry.published.$t?new Date(entry.published.$t).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'';link.appendChild(title);link.appendChild(time);latest.appendChild(link);});syncMobileLatest();}).catch(function(){});};if(window.requestIdleCallback){requestIdleCallback(_fetchLatest,{timeout:2000});}else{setTimeout(_fetchLatest,200);}}
      }
      function navigationRank(title,url){var value=(title+' '+url).toLowerCase();if(/architect|framework|system.design/.test(value)){return 20;}if(/trustlink.pay/.test(value)){return 25;}if(/research|knowledge|paper/.test(value)){return 30;}if(/ecosystem|partner|blurb/.test(value)){return 50;}if(/about/.test(value)){return 60;}if(/contact/.test(value)){return 70;}if(/editorial/.test(value)){return 80;}if(/correct/.test(value)){return 90;}if(/privacy/.test(value)){return 100;}return 65;}
      function navigationLabel(title,url){var value=(title+' '+url).toLowerCase();if(/architect/.test(value)){return'Architecture';}if(/research|knowledge|paper/.test(value)){return'Research';}if(/trustlink.pay|ecosystem|partner|blurb/.test(value)){return'TrustLink Pay';}if(/about/.test(value)){return'About';}if(/contact/.test(value)){return'Contact';}if(/editorial/.test(value)){return'Editorial Policy';}if(/correct/.test(value)){return'Corrections';}if(/privacy/.test(value)){return'Privacy';}return title;}
      function buildAutomaticNavigation(entries){if(!nav||nav.querySelector('a')){arrangeNavigation();return;}var pages=[];entries.forEach(function(entry,index){var alt=alternate(entry);if(!alt){return;}pages.push({title:entry.title.$t,url:alt.href,rank:navigationRank(entry.title.$t,alt.href),index:index});});pages.sort(function(a,b){return a.rank-b.rank||a.index-b.index;});var box=document.createElement('div'),list=document.createElement('ul');box.className='widget-content navigation-automatic';function add(label,url,className){var item=document.createElement('li'),anchor=document.createElement('a'),destination=url.split(/[?#]/)[0].replace(/\/$/,'');anchor.href=url;anchor.textContent=label;if(className){anchor.className=className;}if(destination===current){item.className='selected';anchor.classList.add('active');}item.appendChild(anchor);list.appendChild(item);}add('Home','/','home-link');pages.filter(function(item){return item.rank<=30;}).forEach(function(item){add(navigationLabel(item.title,item.url),item.url,'');});add('Updates','/p/updates.html','updates-link'+(isIndex||isPost||isLabelPage?' active':''));pages.filter(function(item){return item.rank>30;}).forEach(function(item){add(navigationLabel(item.title,item.url),item.url,'');});box.appendChild(list);nav.appendChild(box);arrangeNavigation();}
      if(needNav){fetch('/feeds/pages/default?alt=json&max-results=30').then(function(r){return r.json();}).then(function(data){buildAutomaticNavigation((data.feed&&data.feed.entry)||[]);}).catch(function(){buildAutomaticNavigation([]);});}
      if(latest){latest.classList.add('loaded');}
      if(latest && latest.innerHTML.trim()===''){latest.innerHTML='<small>Loading research updates&#8230;</small>';}
      /* Updates page: live feed (Blogger strips page-body scripts) */
      if(isIndex){(function(){
        var KNOWN=['Protocol','Payments','Privacy','Education','Research','Updates'];
        var list=document.getElementById('up-list');
        if(!list){return;}
