(function() {
  function wrapTables(root) {
    var tables = root.querySelectorAll ? root.querySelectorAll(".post-body table") : [];
    tables.forEach(function(table) {
      if (table.parentElement && !table.parentElement.classList.contains("table-scroll")) {
        var wrapper = document.createElement("div");
        wrapper.className = "table-scroll";
        table.parentNode.insertBefore(wrapper, table);
        wrapper.appendChild(table);
      }
    });
  }

  // Wrap existing tables (if any loaded natively)
  document.addEventListener("DOMContentLoaded", function() {
    wrapTables(document);
  });

  // Watch for dynamically loaded posts (SPA behavior)
  var observer = new MutationObserver(function(mutations) {
    mutations.forEach(function(mutation) {
      mutation.addedNodes.forEach(function(node) {
        if (node.nodeType === 1) { // Element node
          if (node.classList && node.classList.contains("post-body")) {
             wrapTables(node.parentNode);
          } else if (node.querySelectorAll) {
             wrapTables(node);
          }
        }
      });
    });
  });

  // Start observing the body for injected posts
  if (document.body) {
    observer.observe(document.body, { childList: true, subtree: true });
  } else {
    document.addEventListener("DOMContentLoaded", function() {
      observer.observe(document.body, { childList: true, subtree: true });
    });
  }
})();
