  window.addEventListener('load', function() {
    function initCookie() {
      if (window.cookieconsent) {
        window.cookieconsent.initialise({
          "palette": {
            "popup": { "background": "#191814", "text": "#f4f0e8" },
            "button": { "background": "#194b34", "text": "#ffffff" }
          },
          "theme": "classic",
          "position": "bottom-right",
          "content": {
            "message": "We use cookies and analytics to ensure you get the best experience and to understand how our site is used.",
            "dismiss": "Accept",
            "link": "Privacy Policy",
            "href": "https://tsn-protocol.blogspot.com/p/privacy-policy.html"
          }
        });
      }
    }
    if ('requestIdleCallback' in window) {
      requestIdleCallback(initCookie, { timeout: 3000 });
    } else {
      setTimeout(initCookie, 1500);
    }
  });
