// Add image metadata and responsive Blogger image candidates after post markup loads.
(function(){
  function fixImageAttrs(){
    var postTitle = document.querySelector('.post-title, h1.entry-title');
    var titleText = postTitle ? postTitle.textContent.trim() : '';
    var imgs = document.querySelectorAll('.post-body img, .post-outer img');
    imgs.forEach(function(img){
      if(!img.getAttribute('alt')){ img.setAttribute('alt', titleText); }
      if(!img.getAttribute('title')){ img.setAttribute('title', titleText); }
    });
    document.querySelectorAll('.post-body img').forEach(function(img){
      var src = img.getAttribute('src') || '';
      if(src.indexOf('blogger.googleusercontent.com/img/') === -1){ return; }
      var marker = /\/(?:w\d+(?:-h\d+)?|s\d+(?:-rw)?)\//;
      if(!marker.test(src)){ return; }
      var medium = src.replace(marker, '/w480/');
      var large = src.replace(marker, '/w960/');
      img.setAttribute('srcset', medium+' 480w, '+large+' 960w');
      img.setAttribute('sizes', '(max-width: 600px) calc(100vw - 2rem), 760px');
      if(img.src !== medium){ img.setAttribute('src', medium); }
    });
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', fixImageAttrs);
  } else {
    fixImageAttrs();
  }
})();
